package service;import model.*;import repository.Repository;import exception.*;import java.nio.file.*;import java.util.*;import util.Validator;public class BankService{private final Repository<Account> repo=new Repository<>();public BankService(){try{for(Account a:StatePersister.load(Path.of("data/accounts.ser")))repo.save(a);}catch(Exception e){System.err.println("Starting with empty store: "+e.getMessage());}}public Account openAccount(String owner,long opening,int type)throws BankException{if(owner==null||owner.isBlank())throw new BankException("Owner name required");if(opening<0)throw new InvalidAmountException("Opening amount cannot be negative");Account a=switch(type){case 1->new SavingsAccount(owner,opening,500);case 2->new CurrentAccount(owner,opening,10000);case 3->new FixedDepositAccount(owner,opening);default->throw new BankException("Invalid account type");};repo.save(a);TransactionLog.append(a.getAccountNumber()+"|OPEN|"+opening);return a;}public Account get(String id)throws AccountNotFoundException{Account a=repo.findById(id);if(a==null)throw new AccountNotFoundException(id);return a;}public void deposit(String id,long amount)throws BankException{Account a=get(id);a.deposit(amount);TransactionLog.append(id+"|DEPOSIT|"+amount);}public void withdraw(String id,long amount)throws BankException{Account a=get(id);a.withdraw(amount);TransactionLog.append(id+"|WITHDRAW|"+amount);}public void transfer(String from,String to,long amount)throws BankException{Account a=get(from),b=get(to);a.transferTo(b,amount);TransactionLog.append(from+"|TRANSFER|"+amount+"|"+to);}public String statement(String id)throws BankException{Account a=get(id);return "MINIBANK STATEMENT\n"+a+"\nInterest rate: "+a.interestRate()+"%";}public List<Account> listAccounts(){return repo.findAll();}public void save(){try{Files.createDirectories(Path.of("data"));StatePersister.save(repo.findAll(),Path.of("data/accounts.ser"));}catch(Exception e){System.err.println("Save failed: "+e.getMessage());}}public String report(){return ReportGenerator.generate();}public boolean validMobile(String s){return Validator.isValidMobile(s);}}
